mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.z += time * 0.6;
  vec3 q = mod(p, 1.5) - 0.75;
  return length(q) - (0.15 + 0.05 * sin(dot(floor(p/1.5), vec3(1.0)) + time * 3.0));
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.0, -1.0);
  vec3 rd = normalize(vec3(p, 1.5));
  float t = 0.0;
  float sporeGlow = 0.0;
  for (int i = 0; i < 45; i++) {
    float d = map(ro + rd * t);
    sporeGlow += 0.015 / (0.05 + abs(d));
    if (d < 0.003 || t > 10.0) break;
    t += d * 0.75;
  }
  vec3 col = sporeGlow * vec3(1.0, 0.3, 0.8) * (0.8 + 0.4 * bass);
  ret = col;
}
